import java.io.*;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Primeira linha: N (o comprimento real guarda-se pela própria palavra)
        br.readLine();
        String p = br.readLine();
        if (p == null) p = "";
        p = p.trim();
        int n = p.length();

        String ans = null;
        if (n >= 2) {
            char[] s = p.toCharArray();
            int[] a = new int[26];   // frequências da raiz (prefixo de tamanho L)
            int[] cur = new int[26]; // frequências parciais do bloco atual

            outer:
            for (int L = 1; L <= n / 2; L++) { // raiz precisa de >= 2 blocos
                if (n % L != 0) continue;
                Arrays.fill(a, 0);
                for (int i = 0; i < L; i++) a[s[i] - 'a']++;
                Arrays.fill(cur, 0);
                int blocks = n / L;
                boolean ok = true;
                for (int b = 1; b < blocks && ok; b++) {
                    int st = b * L;
                    int en = st + L;
                    for (int i = st; i < en; i++) {
                        int c = s[i] - 'a';
                        // se exceder a contagem da raiz, o bloco não é anagrama
                        if (++cur[c] > a[c]) { ok = false; break; }
                    }
                    if (ok) {
                        // cur <= a sempre valeu e a soma de ambos e' L => cur == a
                        // desfaz as contagens para o proximo bloco
                        for (int i = st; i < en; i++) cur[s[i] - 'a']--;
                    }
                }
                if (ok) {
                    ans = new String(s, 0, L); // menor raiz (L crescente)
                    break outer;
                }
            }
        }

        System.out.println(ans == null ? "*" : ans);
    }
}
